'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='program-production-v1', uid=()=>crypto.randomUUID(), dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-CA',{month:'short',day:'numeric'});
const seed={assets:[{id:'AO-0001',title:'Arriving here',speaker:'Adam · example',type:'Audio',stage:'Planned',week:'01',duration:'—',version:1},{id:'AO-0002',title:'Meeting the urge',speaker:'Guest voice · example',type:'Audio',stage:'In edit',week:'02',duration:'—',version:1},{id:'AO-0003',title:'The people behind The Program',speaker:'Team · example',type:'Video',stage:'Planned',week:'—',duration:'—',version:1}],sessions:[{id:'session1',title:'Production kickoff',date:'2026-11-09',time:'10:00',duration:'60',talent:'Adam + Thom',location:'Regina · location to confirm',kind:'Planning',status:'Tentative',notes:'Example planning entry. Confirm launch priorities, recording space and delivery specifications.'},{id:'session2',title:'Room and microphone tests',date:'2026-11-12',time:'09:30',duration:'90',talent:'Thom',location:'Recording space · to confirm',kind:'Recording',status:'Tentative',notes:'Example entry. Capture voice tests and room tone before choosing the house preset.'},{id:'session3',title:'First contributor recording',date:'2026-11-16',time:'10:00',duration:'120',talent:'Contributor · to confirm',location:'Regina · to confirm',kind:'Recording',status:'Tentative',notes:'Example entry. Assign approved script before confirming.'},{id:'session4',title:'First master review',date:'2026-11-20',time:'13:00',duration:'45',talent:'Adam + Thom',location:'Remote',kind:'Review',status:'Tentative',notes:'Example entry. Review tone, pacing, loudness and export requirements.'}],scripts:[{id:'script1',title:'Arriving here',piece:'AO-0001',talent:'Example contributor',version:1,status:'Draft',body:'EXAMPLE SCRIPT — NOT FOR RECORDING\n\nWelcome. Take a moment to arrive.\n\nThere is nothing you need to get right in this moment. Let your attention settle, and notice what is already here.\n\n[Pause]\n\nThis is demonstration copy for testing script review and downloads. Replace it with company-approved content.',ack:false},{id:'script2',title:'Recording welcome · download example',piece:'DEMO',talent:'Example contributor',version:1,status:'Approved',body:'DEMONSTRATION ONLY — NOT A COMPANY-APPROVED SCRIPT\n\nWelcome to your recording session. We will take this one section at a time. If you need to pause, ask a question, or try a line again, you can.\n\nThis sample demonstrates the approved-script workflow. Replace it with an actual approved script before production.',ack:false}],sops:[{"id": "sop-sound-design", "title": "Sound design", "category": "Sound design", "owner": "Audio Producer", "version": 1, "status": "Draft", "summary": "Emotional cue maps, tonal scoring, key consistency, mix standards and final sound-design QC.", "body": "SOURCE DOCUMENT · NOVEMBER 4, 2026\nOwner: Audio Producer\nReview: Producer/Director before picture lock\nApproval status: not specified in source; imported as Draft for review.\nSource version: not specified. Library version starts at 1.\n\nFor the original table layouts, open the source PDF.\n\n1. Purpose and scope\nEvery piece The Program ships gets a score built from key-locked tonal elements, not a\nplaylist of licensed songs. The producer makes the musical and emotional decisions; the\nlibrary supplies the parts.\nApplies to: long-form video, podcast video cuts, branded stories and sponsor reads\nproduced by The Program.\nOwner: Audio Producer. Reviewed by: Producer/Director before picture lock.\nWhy we work this way\nStory leads, music follows. A song arrives with its own shape (intro, verse, chorus,\nbridge). Our edits don't share that shape, so songs drag the cut somewhere it didn't\nask to go.\nOne key, one world. When every cue lives in the same key, cues can stack, overlap\nand hand off without clashes. A whole film sounds like one composed piece.\nFewer licences, less risk. The benchmark film below used one licensed track in 18\nminutes, and only for the sponsor segment.\nSilence is a tool. Music drops out on purpose so the listener's ears reset and the next\ncue lands harder.\n2. The toolkit\nTonal sound effects are musical building blocks that come in all 12 keys. They are neither\nsound effects (noise like whooshes and booms) nor songs (a finished emotional arc).\nTreat them like Lego: stack layers in one key to build a score.\nElement\nWhat it does\nWhen to reach for it\nStory loop\nHolds one emotion for 16 bars,\nloopable\nThe bed under a section or\nargument\nTexture / drone\nSustained pad or string field\nunderneath\nAdd depth or tension without new\nmelody\n\nStory loop anatomy\n1. 16 bars total, one emotion the whole way (curiosity, questioning, momentum,\nmelancholy).\n2. Bars 1–8: one element only. Keep it sparse.\n3. Bars 9–16: add one small layer to keep the listener leaning in. Nothing dramatic.\n4. Loop again as many times as the scene needs. The loop holds the feeling; the edit\ndecides how long.\nLoops are catalogued by emotion name. Pick the loop by the feeling of the scene, not by\ngenre.\n3. Pre-production: map before you score\nNo cue goes on the timeline until the emotional map is done. Work from the locked script\nor a transcript of the assembly.\n1. Break the piece into sections. Mark every change of topic, speaker, or voice (VO vs\ninterview).\n2. Name one emotion per section. Use the library's loop names: curious, questioning,\nmomentum, threat, sad, melancholy.\n3. Flag the payoff lines. Find the lines the edit builds toward. These get risers and hits.\nElement\nWhat it does\nWhen to reach for it\nTonal riser\nBuilds tension into a moment, in\nkey\nLeading into a punchline or reveal\nTonal transition\nBridges one cue or scene into\nthe next\nSection changes, cut points\nTonal hit\nA single pitched accent\nLanding a name, number or key\nword\nMelody\nA short tonal line\nSignal a turn, a disaster, a new idea\nChord\nprogression\nHarmonic movement over a bed\nLift a section emotionally\nLicensed song\nA complete track\nSponsor reads or moments outside\nthe story\n\n4. Flag the silences. Pick 2–3 places where music drops out entirely (a hard image, a\nheavy fact, a breath before a turn).\n5. Choose a home key. One minor key for the whole piece (the benchmark used A\nminor).\n6. Choose a contrast key. One related key for a perspective shift (the benchmark used\nD minor, then returned home).\n7. Mark non-story segments. Sponsor reads and ads get a licensed track or a separate\nbed, then hand back to the score.\nDeliverable: a cue map with columns for timecode, section, emotion, key, element type,\nand notes. Share it with the director before scoring.\n4. Scoring workflow\nBuild the score in layers, bed first, accents last. Each pass has one job.\n1. Cold open. Start with a tonal riser into a short, rhythmic loop (a ticking clock loop\nworks for urgency), then a tonal transition into the first full story loop.\n2. Lay the beds. Place one story loop per section from the cue map. Loop it as many\ntimes as the section runs (the benchmark looped some loops 2.5–4 times).\n3. Ride the meaning. When the words describe change, let the music echo it. Example: a\nloop speeds up as the speaker says the cycle sped up.\n4. Add textures. Fade a drone or string field under a loop to deepen a moment without\nadding melody. Keep it in the home key.\n5. Build to the payoff lines. Stack a riser, a pad and a symbolic loop (a clock for running\nout of time) under the line the section builds toward.\n6. Place tonal hits. Land a pitched hit on a key word or name. Bury it low in the mix; it\nshould be felt, not noticed.\n7. Mark turns with melody. Bring in a short melody over the drone when the story turns\n(a disaster, a new era).\n8. Shift key for a shift in voice. Move to the contrast key when a new perspective\nspeaks, then return home when the narrator takes back over.\n9. Lift with chords. Add a chord progression when a section needs emotional weight.\n10. Cut the music. Drop all music at the flagged silences. Bring it back with a subtle tonal\nriser.\n\n11. Handle sponsor segments. Use the one licensed track here only, matched to the\nhost's personality. Hand back to the score with a story loop.\n12. Land the ending. Close on a loop that matches the final feeling (the benchmark\nended on \"melancholy\") and end cleanly with the last line.\n5. Mix standards\nDialogue is king; the score supports and never competes. The source film shows accents\nburied so low they're barely audible, and that's the point.\nFade loops in and out; avoid hard starts unless a cut calls for it.\nNever layer elements from different keys at the same time.\nCheck every transition on headphones and laptop speakers.\nName stems by element type (Dialogue, Loops, Textures, Accents, Licensed) for\nrevisions.\n6. Benchmark: Matt D'Avella's consumerism film\nAn 18-minute documentary on fast fashion, scored almost entirely from tonal elements, as\nbroken down by Multiply Sound (Film Score Collection Vol. 3). Use it as the reference\nstandard.\nLayer\nMix rule\nDialogue / VO\nAlways on top, clear and consistent\nStory loop\nSits under dialogue; duck under speech\nTexture / drone\nFelt more than heard; fade in and out, never cut\nTonal hit / swell\nBuried; an accent you'd miss if it were gone\nRiser / transition\nSubtle; shape the edit, don't announce it\nLicensed song\nSponsor segments only; may sit higher\nElement\nCount\nStory loops\n9\n\nCue walkthrough\nElement\nCount\nTonal transitions, risers and hits\n23\nTextures and drones\n5\nChord progressions\n1\nTonal melodies\n1\nLicensed songs\n1 (sponsor read only)\nSection\nWhat happens on screen\nSound design move\nCold open\nHost asks where people buy\nclothes\nTonal riser into clock loop, transition\ninto first story loop\nHaul culture\nSocial media hauls\nString-field texture fades in under\nthe loop; buried swell as people enter\na room\nPayoff line\nHost says consumerism has\ngone too far\nClock bell, risers and a pad build to\nthe line; clock = time running out\nDisaster footage\nHard-to-watch images\nNo music\nHistory\nSeasonal clothing, then fast\nfashion\nDrone + melody; next loop speeds up\nas \"sped up\" is said\nUltra fast fashion\nZara, Shein named\nBuried tonal hit on the brand name;\nnew loop when story shifts\nInterview handoff\nVO cuts back to interview\nMusic stops; break, then subtle riser\nback in\nPrices\nPrice data, inflation\nCalmer loop, looped four times\nHaul interview\nInfluencer perspective\nKey change to D minor with piano;\nback to A minor after\nOverconsumption\nBuying more, keeping less\nChord progression enters\nSocial media\nMeta settlement\nSadder overtone replaces curious\nloops\n\n7. QC checklist\nTick every box before the mix goes to the director.\nThe rule of thumb: if a cue doesn't reflect what's being said, cut it.\nSection\nWhat happens on screen\nSound design move\nSponsor\nSquarespace read\nThe one licensed song (jazz), then\nstraight back to score\nSupply chain\nWho pays the price\n\"Threat\" loop, looped 2.5 times; small\nriser and hit\nEnding\nHost's conclusion\n\"Melancholy\" loop; ends cleanly on\nthe last line\nCue map shared and approved before scoring\nEvery section has one named emotion and one story loop\nAll elements in the home key, except planned contrast-key moments\nContrast key returns home when the perspective returns\nPayoff lines have a riser or hit building to them\nAt least one intentional music-free break\nAccents buried under dialogue; nothing distracts from speech\nLicensed music limited to sponsor or non-story segments\nEnding loop matches the final emotion and ends on the last line\nChecked on headphones and laptop speakers\nStems named and exported by element type", "sourceUrl": "/guides/sound-design-sop.pdf"},{id:'sop1',title:'On-camera recording',category:'Talent preparation',owner:'Owner to assign',version:1,status:'Draft',summary:'Preparation, presence, delivery styles and recording-day checklist.',body:'WORKING LIBRARY ENTRY\n\nSource: On-Camera Recording SOP, version 1.0, November 2026. Original PDF has not been uploaded to this preview.\n\nBefore recording\n• Confirm the purpose and audience.\n• Practise your first and last lines.\n• Read the script aloud and ask about unfamiliar wording.\n• Bring comfortable clothing and a backup top.\n\nOn the day\n• Confirm whether the piece is scripted, prompted or an interview.\n• Ask for breaks, clarification or another take whenever needed.\n• Pause and restart the sentence after a stumble.\n\nApply delivery guidance to the format: a quiet guided practice and an energetic video need different direction.\n\nTo publish this SOP: assign an owner, review the source document and approve the current version.'},{id:'sop2',title:'Recording-session checklist',category:'Recording',owner:'Production',version:1,status:'Draft',summary:'A repeatable setup, from room tone to confirmed pickups.',body:'DRAFT — REVIEW BEFORE USE\n\nBefore talent arrives\n□ Check room noise, microphone position and signal.\n□ Confirm recording format, power and available storage.\n□ Confirm the approved script version.\n□ Make a short test recording and listen back.\n\nDuring the session\n□ Log content ID, take number and speaker.\n□ Record room tone.\n□ Mark preferred takes and pickups.\n\nBefore wrapping\n□ Listen to critical lines and pickups.\n□ Verify recordings open and have audio.\n□ Make and verify a second copy before clearing cards.'},{id:'sop3',title:'Media intake & naming',category:'File management',owner:'Production',version:1,status:'Draft',summary:'Preserve originals, register working files and prevent duplicate imports.',body:'DRAFT — PROPOSED STANDARD\n\n1. Preserve original camera and recorder names.\n2. Assign a permanent content ID (AO-0001).\n3. Link every recording, edit and master to that ID.\n4. Working name: AO-0001_20261116_adam_take03.wav\n5. Edit: AO-0001_arriving-here_edit_v001.wav\n6. Master: AO-0001_arriving-here_master_v001.wav\n7. Never overwrite an original.\n8. Confirm copy completeness and checksum before processing.\n\nHotfolder automation and duplicate checks are not connected in this preview.'},{id:'sop4',title:'Mastering & delivery',category:'Audio post-production',owner:'Production',version:1,status:'Draft',summary:'From edited dialogue to a reviewed, traceable delivery master.',body:'DRAFT — TARGETS REQUIRE SIGN-OFF\n\n1. Finish take selection and pacing before mastering.\n2. Select an agreed Auphonic preset.\n3. Preserve pauses and breaths appropriate to the format.\n4. Measure loudness, true peak and duration after processing.\n5. Listen for artifacts, missing words and abrupt joins.\n6. Reconcile the transcript against the final edit.\n7. Approve an exact master version.\n8. Package only approved files using developer specifications.\n\nThe proposed -18 LUFS / -1.5 dBTP house targets remain provisional.'},{id:'sop5',title:'Video review & export',category:'Video post-production',owner:'Production',version:1,status:'Draft',summary:'Check picture, audio, captions and the destination before export.',body:'DRAFT — REVIEW BEFORE USE\n\n□ Confirm aspect ratio, resolution and frame rate.\n□ Check names, titles and approved script changes.\n□ Review dialogue, music and audio sync.\n□ Proof captions against the final edit.\n□ Check music and image usage permissions.\n□ Watch the full exported file.\n□ Record the approved version and delivery destination.'},{id:'sop6',title:'Archive & handover',category:'Delivery & archive',owner:'Production',version:1,status:'Draft',summary:'Leave every piece findable, recoverable and ready for the next producer.',body:'DRAFT — REVIEW BEFORE USE\n\n□ Preserve originals, project files and approved masters.\n□ Store scripts, transcripts and version history alongside asset records.\n□ Document processing presets and export specifications.\n□ Verify a separate backup and test a restore.\n□ Assign company ownership of accounts and storage.\n□ Export the catalogue and document folder locations.\n\nA local browser export is not a media backup.'}],tasks:[{id:'t1',title:'Confirm January 1 launch essentials with Adam',done:false},{id:'t2',title:'Agree delivery formats with the app developer',done:false},{id:'t3',title:'Connect company storage and team sign-in',done:false},{id:'t4',title:'Test one complete recording-to-delivery workflow',done:false}],queue:[]};
let state;try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{state=structuredClone(seed)}
if(!state.sops.some(s=>s.id==='sop-sound-design')){state.sops.push(structuredClone(seed.sops.find(s=>s.id==='sop-sound-design')));save()}
let route='overview',filter='',tabFilter='All',scheduleView='list',month=10,year=2026;
const routes=[['overview','◫','Overview'],['schedule','▦','Production schedule'],['media','♫','Media library'],['processing','◉','Audio desk'],['scripts','≡','Scripts'],['sops','▤','SOP library'],['talent','♙','Talent portal'],['connections','⌁','Connections']];
const stages=['Planned','Recorded','In edit','Ready for review','Approved','Delivered'];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is full. Export your workspace before continuing.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function tag(t){const color=/Approved|Confirmed|Delivered|Complete/.test(t)?'green':/Draft|Tentative|Planned|Not connected/.test(t)?'amber':/edit|Review|review/.test(t)?'blue':'';return `<span class="tag ${color}">${esc(t)}</span>`}
function head(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="row">${actions}</div></div>`}
function btn(label,action,primary=false){return `<button class="btn ${primary?'primary':''}" data-action="${action}">${label}</button>`}
function empty(t){return `<div class="empty">${t}</div>`}
function agenda(s){return `<div class="agenda-item"><div class="datebox"><small>${new Date(s.date+'T12:00:00').toLocaleDateString('en',{month:'short'})}</small><strong>${Number(s.date.slice(-2))}</strong></div><div class="agenda-body"><button class="text-link" style="text-decoration:none;color:var(--ink);font-size:13px;font-weight:600" data-session="${s.id}">${esc(s.title)}</button><div class="agenda-meta">${esc(s.time)} · ${esc(s.duration)} min · ${esc(s.talent)}</div><div class="agenda-meta">${esc(s.location)}</div></div>${tag(s.status)}</div>`}
function assetRows(items){return items.map(a=>`<tr><td><div class="row"><div class="file-icon">${a.type==='Video'?'MOV':'WAV'}</div><div class="file-name">${esc(a.title)}<small>${esc(a.id)} · v${String(a.version).padStart(3,'0')}</small></div></div></td><td>${esc(a.speaker)}</td><td>${tag(a.type)}</td><td><select class="status-select" aria-label="Stage for ${esc(a.title)}" data-stage="${esc(a.id)}">${stages.map(s=>`<option ${a.stage===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${esc(a.week)}</td><td><button class="text-link" data-asset="${esc(a.id)}">Details →</button></td></tr>`).join('')}
function assetTable(items){return `<div class="table-wrap"><table><thead><tr><th>Content piece</th><th>Voice / contributor</th><th>Format</th><th>Stage</th><th>Week</th><th></th></tr></thead><tbody>${assetRows(items)}</tbody></table>${items.length?'':empty('No matching content pieces.')}</div>`}
function overview(){let next=[...state.sessions].filter(s=>!['Cancelled','Complete'].includes(s.status) && s.date>=new Date().toLocaleDateString('en-CA',{timeZone:'America/Regina'})).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];let approved=state.assets.filter(a=>['Approved','Delivered'].includes(a.stage)).length, pct=state.assets.length?Math.round(approved/state.assets.length*100):0;return head('PRODUCTION DESK','Production overview','Your next session, current progress and the work that needs attention.',btn('＋ New session','new-session',true))+`<section class="dashboard-focus"><div><div class="eyebrow">UP NEXT</div><h2>${next?esc(next.title):'Plan your next session'}</h2><p>${next?`${esc(dateLabel(next.date))} · ${esc(next.time)} · ${esc(next.talent)}`:'Give the next recording a place on the calendar.'}</p><span>${next?esc(next.location):'Recording, planning or review'}</span></div><div>${next?`<button class="btn primary" data-session="${esc(next.id)}">View session →</button>`:btn('Schedule a session →','new-session',true)}<a href="#schedule">See full schedule</a></div></section><div class="dashboard-section-label">AT A GLANCE <span>Local workspace activity</span></div><div class="stats"><div class="stat"><span class="label">Content pieces</span><span class="stat-icon">▤</span><strong>${state.assets.length.toString().padStart(2,'0')}</strong><small>Tracked in this browser</small></div><div class="stat"><span class="label">Recording sessions</span><span class="stat-icon">◉</span><strong>${state.sessions.filter(s=>s.kind==='Recording').length.toString().padStart(2,'0')}</strong><small>Planned · confirm with contributors</small></div><div class="stat"><span class="label">Ready for review</span><span class="stat-icon">◷</span><strong>${state.assets.filter(a=>a.stage==='Ready for review').length.toString().padStart(2,'0')}</strong><small>Waiting for a listening pass</small></div><div class="stat"><span class="label">Library procedures</span><span class="stat-icon">▧</span><strong>${state.sops.length.toString().padStart(2,'0')}</strong><small>${state.sops.filter(s=>s.status==='Draft').length} drafts to review</small></div></div><div class="launch"><div class="launch-mark">01<small>JANUARY 2027</small></div><div class="launch-main"><div class="row spread"><h3>A clear path to launch</h3><span class="small">${approved} / ${state.assets.length} pieces approved</span></div><div class="progress"><span style="width:${pct}%"></span></div><p class="launch-note">Example catalogue · confirm the launch content list before using this as a readiness measure.</p></div>${tag('Planning')}</div><div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><h2>On the horizon</h2><a href="#schedule">Full schedule ↗</a></div>${[...state.sessions].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,3).map(agenda).join('')||empty('No sessions yet.')}</section><section class="panel"><div class="panel-head"><h2>The production shelf</h2><a href="#media">All content ↗</a></div>${assetTable(state.assets.slice(0,4))}</section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>First things first</h2>${tag('Setup')}</div><div class="panel-body">${state.tasks.map(t=>`<label class="task-row ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span>${esc(t.title)}</span></label>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Connected to the desk</h2><a href="#connections">Manage ↗</a></div><div class="panel-body">${[['A','Auphonic','Audio processing'],['△','Google Drive','Media storage'],['⌘','Local worker','Hotfolders & transcription']].map(([i,n,d])=>`<div class="connection-row"><div class="row"><span class="connection-icon">${i}</span><div>${n}<small>${d}</small></div></div>${n==='Google Drive'&&window.HubDrive&&HubDrive.connected()?'<span class="tag green">Connected</span>':'<span class="tag">Not connected</span>'}</div>`).join('')}</div></section><div class="notice"><b>A workspace that stays useful.</b><br>Every script, session and file will share one content ID. Nothing gets lost between recording and delivery.</div></div></div>`}
function schedule(){let items=state.sessions.filter(s=>[s.title,s.talent,s.kind,s.location].join(' ').toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return head('PLAN THE WORK','Production schedule','Recording days, review sessions and milestones. All times: America/Regina.',btn('＋ New session','new-session',true))+`<div class="notice">Sample sessions are tentative. Editing this schedule does not send invitations or update anyone else’s calendar.</div><div class="toolbar"><input id="filter" aria-label="Search sessions" placeholder="Search sessions or contributors…" value="${esc(filter)}"><button class="btn ${scheduleView==='list'?'primary':''}" data-view="list">Agenda</button><button class="btn ${scheduleView==='month'?'primary':''}" data-view="month">Month</button><button class="btn ${scheduleView==='board'?'primary':''}" data-view="board">Production board</button>${btn('Export calendar','calendar-export')}</div>${scheduleView==='list'?`<section class="panel"><div class="panel-head"><h2>Upcoming sessions</h2><span class="small muted">${items.length} sessions</span></div>${items.map(agenda).join('')||empty('No matching sessions.')}</section>`:scheduleView==='month'?calendar(items):`<div class="board">${['Planned','In edit','Ready for review','Approved'].map(st=>`<div class="board-col"><h3>${st}<span>${state.assets.filter(a=>a.stage===st).length}</span></h3>${state.assets.filter(a=>a.stage===st).map(a=>`<div class="board-card"><span class="mono muted">${esc(a.id)}</span><h3>${esc(a.title)}</h3><p>${esc(a.speaker)}</p><div class="mt">${tag(a.type)} <button class="text-link" data-asset="${a.id}">Open →</button></div></div>`).join('')}</div>`).join('')}</div>`}`}
function calendar(items){let start=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();return `<section class="panel calendar-panel"><div class="panel-head"><h2>${new Date(year,month).toLocaleDateString('en',{month:'long',year:'numeric'})}</h2><div class="row"><button class="btn small" data-month="-1" aria-label="Previous month">←</button><button class="btn small" data-month="1" aria-label="Next month">→</button></div></div><div class="calendar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-label">${d}</div>`).join('')}${Array.from({length:Math.ceil((start+days)/7)*7},(_,i)=>{let day=i-start+1,date=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;return day<1||day>days?'<div class="cal-day empty"></div>':`<div class="cal-day ${date===new Date().toLocaleDateString('en-CA',{timeZone:'America/Regina'})?'today':''}"><strong>${day}</strong>${items.filter(s=>s.date===date).map(s=>`<button class="cal-event" data-session="${s.id}">${esc(s.time)} ${esc(s.title)}</button>`).join('')}</div>`}).join('')}</div></section>`}
function media(){let items=state.assets.filter(a=>(tabFilter==='All'||a.type===tabFilter)&&[a.title,a.id,a.speaker].join(' ').toLowerCase().includes(filter.toLowerCase()));return head('EVERY FILE HAS A HOME','Media library','Recordings, edits and masters, connected by a permanent content ID.',btn('＋ Content piece','new-asset',true))+`<div class="filter-tabs">${['All','Audio','Video'].map(t=>`<button class="${tabFilter===t?'active':''}" data-tab="${t}">${t==='All'?'All content':t}</button>`).join('')}</div><div class="dropzone" id="dropzone"><div class="doc-symbol">↥</div><h2>Bring your recordings to the desk.</h2><p>${window.HubDrive&&HubDrive.connected()?'Drop audio or video here. Files upload to the team Google Drive (01_Incoming) and are listed below.':'Select audio or video to stage its file details locally. Files are not uploaded or transcribed yet.'}</p><button class="btn primary" data-action="choose-files">Choose files</button><input id="file-input" type="file" accept="audio/*,video/*,.wav,.mp3,.m4a,.mov,.mp4,.mxf" multiple hidden></div><div class="toolbar"><input id="filter" aria-label="Search media" placeholder="Search title, content ID or contributor…" value="${esc(filter)}">${btn('Export catalogue','catalogue-export')}</div><section class="panel">${assetTable(items)}</section>${state.queue.length?`<section class="panel mt"><div class="panel-head"><h2>${window.HubDrive&&HubDrive.connected()?'Uploads':'Staged file details'}</h2><span class="tag amber">${window.HubDrive&&HubDrive.connected()?'In progress':'Not uploaded'}</span></div><div class="table-wrap"><table><thead><tr><th>Original filename</th><th>Size</th><th>State</th><th></th></tr></thead><tbody>${state.queue.map(q=>`<tr><td class="wrap">${esc(q.name)}</td><td>${(q.size/1048576).toFixed(1)} MB</td><td>${tag(q.state||'Awaiting storage connection')}${q.progress!=null?` <span class="small muted">${Math.round(q.progress*100)}%</span>`:''}</td><td><button class="text-link" data-remove-queue="${q.id}">Remove</button></td></tr>`).join('')}</tbody></table></div></section>`:''}${window.filesPanel?filesPanel():''}`}
function scripts(){let items=state.scripts.filter(s=>(tabFilter==='All'||s.status===tabFilter)&&[s.title,s.talent,s.body].join(' ').toLowerCase().includes(filter.toLowerCase()));return head('WORDS BEFORE THE RECORDING','Script library','Keep drafts, approvals and talent copies on the same page.',btn('＋ New script','new-script',true))+`<div class="toolbar"><input id="filter" aria-label="Search scripts" placeholder="Search titles, contributors or script text…" value="${esc(filter)}"><select id="status-filter" aria-label="Script status">${['All','Draft','Approved','Archived'].map(s=>`<option ${tabFilter===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="cards">${items.map(s=>`<article class="doc-card"><div class="row spread"><span class="mono muted">${esc(s.piece||'UNASSIGNED')}</span>${tag(s.status)}</div><h2>${esc(s.title)}</h2><p>${esc(s.talent||'Talent not assigned')}<br>v${String(s.version).padStart(3,'0')} · ${s.body.trim().split(/\s+/).length} words</p><div class="doc-footer"><span>${s.ack?'✓ Reviewed by talent':'Talent review pending'}</span><button class="text-link" data-script="${s.id}">Read & edit →</button></div></article>`).join('')||empty('No scripts match your search.')}</div>`}
function sops(){let cats=['All',...new Set(state.sops.map(s=>s.category))],items=state.sops.filter(s=>(tabFilter==='All'||s.category===tabFilter)&&[s.title,s.summary,s.body].join(' ').toLowerCase().includes(filter.toLowerCase()));return head('THE WAY WE MAKE THINGS','SOP library','Practical guidance that makes the next session easier than the last.',btn('＋ New procedure','new-sop',true))+`<div class="toolbar"><input id="filter" aria-label="Search procedures" placeholder="Find a procedure, checklist or keyword…" value="${esc(filter)}"><select id="category-filter" aria-label="Procedure category">${cats.map(c=>`<option ${tabFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="cards">${items.map((s,i)=>`<article class="doc-card"><div class="row spread"><span class="doc-symbol" style="margin:0">${String(i+1).padStart(2,'0')}</span>${tag(s.status)}</div><span class="eyebrow" style="margin-top:17px;margin-bottom:0;font-size:8px">${esc(s.category)}</span><h2>${esc(s.title)}</h2><p>${esc(s.summary)}</p><div class="doc-footer"><span>v${s.version}.0 · ${esc(s.owner)}</span><button class="text-link" data-sop="${s.id}">Open guide →</button></div></article>`).join('')||empty('No matching procedures.')}</div>`}
function talent(){let approved=state.scripts.filter(s=>s.status==='Approved');return head('PREPARED, NOT OVERWHELMED','Talent portal','A preview of the contributor experience. Individual accounts are not connected.',btn('Open teleprompter','teleprompter',true))+`<div class="talent-hero"><div><div class="eyebrow">YOUR NEXT GOOD RECORDING STARTS HERE</div><h2>Your words. Your pace.</h2><p>Read the latest script, get comfortable with the process, and ask for what you need.</p></div><div><span class="tag amber">Example contributor view</span><p>No private access controls yet.</p></div></div><div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><h2>Approved scripts</h2><span class="small muted">${approved.length} available</span></div><div class="panel-body">${approved.map(s=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><div class="row spread"><h3>${esc(s.title)}</h3>${tag('v'+String(s.version).padStart(3,'0'))}</div><p class="small muted" style="margin:7px 0 13px">${esc(s.piece)} · ${esc(s.talent)} · ${s.ack?'Reviewed':'Please review before recording'}</p><div class="row"><button class="btn small" data-read-script="${s.id}">Read script</button><button class="btn small" data-prompter-script="${s.id}">Teleprompter</button><button class="btn small" data-download-script="${s.id}">Download .txt ↓</button><button class="btn small" data-ack="${s.id}" ${s.ack?'disabled':''}>${s.ack?'✓ Reviewed':'Mark reviewed'}</button></div></div>`).join('')||empty('No approved scripts yet. Drafts stay in the production library.')}</div></section><section class="panel"><div class="panel-head"><h2>Before you arrive</h2></div><div class="panel-body"><p class="muted" style="font-size:12px;margin-bottom:17px">Know your message. Read your script aloud. You can pause, ask questions or try another take at any time.</p><button class="btn" data-sop="sop1">Read the preparation guide →</button></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Recording details</h2>${tag('Example')}</div><div class="panel-body"><div class="section-label">YOUR SESSION</div><h3>Contributor session</h3><p class="muted small" style="margin-top:10px">Date, time and location will appear once a confirmed session is assigned to your account.</p><div class="notice mt" style="margin-bottom:0">Talent-specific session assignments will be enabled with sign-in.</div></div></section><section class="panel"><div class="panel-head"><h2>Recording remotely?</h2></div><div class="panel-body"><p class="small muted" style="margin-bottom:14px">Secure contributor uploads will connect to the company’s storage folder.</p><button class="btn w-full" data-connect="Google Drive">View upload setup →</button></div></section></div></div>`}
const integrations=[{name:'Shared NotebookLM',symbol:'N',desc:'A shared reference notebook for the team’s SOPs, approved scripts, transcripts and production notes.',needs:'Group notebook link · company owner · team sharing permissions · agreed source documents',folder:'SOPs / Approved scripts / Transcripts / Production references',pendingLink:true},{name:'Auphonic',symbol:'A',desc:'Send edited audio to an agreed preset, retrieve masters and save processing reports.',needs:'Company account · server-side credential · approved preset · job queue',folder:'Edited audio → Auphonic → review queue'},{name:'Google Drive',symbol:'△',desc:'Receive recordings, keep originals and deliver approved packages to a company-owned folder.',needs:'Company folder · authorized account · resumable uploads · access rules',folder:'01_Incoming / 02_Working / 03_Approved / 04_Delivery'},{name:'Local worker',symbol:'⌘',desc:'Watch folders on your Mac, extract audio and transcribe recordings locally.',needs:'Designated Mac · folder paths · transcription engine · secure dashboard pairing',folder:'Incoming / Ready_to_master / Masters / Needs_attention'},{name:'Team accounts',symbol:'♙',desc:'Give producers, reviewers and talent access to only the material they need.',needs:'Identity provider · company owner · roles · restricted media access',folder:'Producer / Reviewer / Talent / Administrator'},{name:'Shared database',symbol:'▦',desc:'Keep the catalogue, scripts, sessions and approvals synchronized across the team.',needs:'Hosted database · permissions · migrations · backups',folder:'Content / Files / Transcripts / Scripts / Sessions / Approvals'},{name:'Backup & archive',symbol:'↺',desc:'Keep independent media backups and verify that the project can be restored.',needs:'Primary storage · independent backup · retention policy · restore test',folder:'Originals preserved · versions retained · restores verified'}];

function processing(){return head('THE HOUSE SOUND','Audio desk','Consistent finishing, with the final listening decision in your hands.')+`<div class="notice"><b>Integration preview.</b> Auphonic is not connected. The settings below describe the proposed workflow; no audio is processed here.</div><div class="grid-main"><div class="stack"><section class="panel"><div class="panel-head"><h2>From edit to master</h2>${tag('Not connected')}</div><div class="panel-body"><div class="row" style="flex-wrap:wrap;margin-bottom:25px">${['Edited export','Auphonic preset','Quality check','Listening review','Approved master'].map((x,i)=>`${i?'<span class="muted">→</span>':''}<span class="tag">${x}</span>`).join('')}</div><div class="form-grid"><label class="field">Content piece<select>${state.assets.filter(a=>a.type==='Audio').map(a=>`<option>${esc(a.id)} · ${esc(a.title)}</option>`).join('')||'<option>No audio pieces yet</option>'}</select></label><label class="field">Proposed preset<select><option>House spoken word · provisional</option><option>Video dialogue · provisional</option></select></label></div><div class="notice mt"><b>Provisional house targets:</b> −18 LUFS integrated · −1.5 dBTP ceiling.<br>Confirm the sound and developer requirements using a real recording before locking these in.</div><button class="btn primary" data-action="processing-setup">Review connection requirements →</button><p class="small muted mt">Choose takes and edit pacing before mastering. Preserve the pauses that belong to the piece.</p></div></section><section class="panel"><div class="panel-head"><h2>Processing queue</h2><span class="small muted">0 submitted jobs</span></div><div class="empty">Nothing has been submitted.<br><span class="small">Job progress, processing reports and returned masters will appear here after connection.</span></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>The listening checklist</h2></div><div class="panel-body"><p class="reading">□ Voice remains natural
□ Pauses and breaths feel intentional
□ No missing words or processing artifacts
□ Music supports the voice
□ Loudness and true peak measured
□ Transcript matches the final master</p><button class="btn mt" data-sop="sop4">Mastering procedure →</button></div></section><section class="panel"><div class="panel-head"><h2>Where this started</h2></div><div class="panel-body"><p class="muted small">The original audio concept includes the real before-and-after recording and a browser-based processing demonstration.</p><a class="btn mt" href="/proposal/" target="_blank" rel="noopener">Open original audio concept ↗</a></div></section></div></div>`}
function printDoc(d,sop){let print=document.createElement('article');print.id='print-document';let h=document.createElement('h1');h.textContent=d.title;let p=document.createElement('p');p.textContent=`THE PROGRAM · ${sop?'PROCEDURE':'SCRIPT'} · v${d.version} · ${d.status} · Local preview copy`;let body=document.createElement('div');body.className='reading';body.textContent=d.body;print.append(h,p,body);document.body.append(print);window.print();print.remove()}

function connections(){return head('MAKE THE CONNECTIONS','A desk with room to grow.','The interface is ready to explore. These services still need to be configured.',btn('Export workspace','workspace-export'))+`<div class="notice"><b>Working now:</b> local planning, catalogue records, scripts, SOP editing, downloads and calendar exports.<br><b>Still to connect:</b> shared data, authentication, file transfers, transcription and Auphonic processing. No API credentials are collected by this preview.</div><div class="cards">${integrations.map(i=>`<section class="doc-card integration-card"><div class="row spread"><span class="connection-icon">${i.symbol}</span>${tag(i.pendingLink?'Link pending':i.connected?'Connected':'Not connected')}</div><h2>${i.name}</h2><p>${i.desc}</p><div class="code-name">${i.folder}</div>${i.pendingLink?'<div class="notebook-drop"><strong>Drag-and-drop sources</strong><span>Planned · group notebook link to come</span><small>File transfer is not active in this preview.</small></div><button class="btn" disabled>Open group notebook ↗</button>':''}<button class="btn" data-connect="${i.name}">Setup requirements →</button></section>`).join('')}</div><section class="panel mt"><div class="panel-head"><h2>Workspace data</h2><span class="tag">This browser only</span></div><div class="panel-body"><p class="muted small">Export records before moving to another browser. This export includes text and metadata, not media files, credentials or shared storage.</p><div class="row mt">${btn('Download backup .json','workspace-export')}${btn('Restore backup','workspace-import')}${btn('Reset example data','reset')}<input type="file" id="import-input" accept="application/json" hidden></div></div></section>`}
let demoRole;try{demoRole=sessionStorage.getItem('program-demo-role')}catch{}if(!['talent','production'].includes(demoRole))demoRole=null;
function showLanding(mode='home'){
 document.body.classList.add('landing-mode');$('#landing').hidden=false;document.title='Multimedia Hub · AlchemistOne';
 const talent=mode==='login-talent',login=mode!=='home';
 $('#landing').innerHTML=`<div class="landing-wrap"><header class="landing-top"><a class="brand" href="#home">The Program<span>.</span><small>BY ALCHEMISTONE</small></a><span class="landing-preview">TEAM PREVIEW</span></header><main class="landing-main"><div class="landing-eyebrow">ALCHEMISTONE.</div><h1>The Program<span>.</span></h1><p class="landing-subtitle">MultiMedia Hub.</p><div class="landing-rule"></div>${login?`<div class="login-card"><a class="back-home" href="#home">← Back to home</a><h2>${talent?'Talent':'Production'} login</h2><p>${talent?'Your scripts, session preparation and recording details.':'Your schedule, media, scripts and production tools.'}</p><form id="demo-login"><label for="demo-password">Demo password</label><input id="demo-password" type="password" autocomplete="off" required placeholder="Enter demo password" aria-describedby="demo-hint login-error"><div id="demo-hint" class="demo-hint">For this preview, use <code>${talent?'talent123':'production123'}</code></div><p id="login-error" role="alert"></p><button class="btn gold w-full" type="submit">Enter ${talent?'talent portal':'production workspace'} →</button></form></div>`:`<p class="landing-intro">A shared home for the people, words<br>and work behind The Program.</p><div class="entry-cards"><a class="entry-card" href="#login-talent"><span class="entry-symbol">01 / TALENT</span><h2>Ready for your<br>next recording.</h2><p>Scripts, preparation and session details.</p><span class="entry-link">Talent login <span>↗</span></span></a><a class="entry-card" href="#login-production"><span class="entry-symbol">02 / PRODUCTION</span><h2>Everything behind<br>the scenes.</h2><p>Plan, produce, review and deliver.</p><span class="entry-link">Production login <span>↗</span></span></a></div>`}<p class="landing-disclaimer">Demo logins only. These passwords do not protect private information.<br>Team accounts will be connected when hosting is confirmed.</p></main><footer class="landing-footer"><span>ALCHEMISTONE · THE PROGRAM</span><span>One place. A little more clarity.</span></footer></div>`;
 if(login)$('#demo-login').onsubmit=e=>{e.preventDefault();const expected=talent?'talent123':'production123';if($('#demo-password').value!==expected){$('#login-error').textContent='That demo password doesn’t match. Try the password shown above.';return}demoRole=talent?'talent':'production';try{sessionStorage.setItem('program-demo-role',demoRole)}catch{}location.hash=talent?'talent':'overview';render()};
}
function render(){route=location.hash.slice(1)||'home';if(['home','login-talent','login-production'].includes(route))return showLanding(route);if(!demoRole)return showLanding(route==='talent'?'login-talent':'login-production');if(demoRole==='talent'&&route!=='talent')route='talent';document.body.classList.remove('landing-mode');$('#landing').hidden=true;if(!routes.some(r=>r[0]===route))route='overview';$('#nav').innerHTML=(demoRole==='talent'?routes.filter(r=>r[0]==='talent'):routes).map(([r,i,t],idx)=>`${r==='connections'?'<div class="nav-divider"></div>':''}<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}><span class="nav-icon">${i}</span>${t}${r==='sops'?`<span class="nav-count">${state.sops.length}</span>`:''}</a>`).join('');$('.sidebar-foot strong').textContent=demoRole==='talent'?'Talent workspace':'Production workspace';$('.search-trigger').hidden=demoRole==='talent';$('#breadcrumb').textContent=routes.find(r=>r[0]===route)[2];$('#main').dataset.page=route;$('#main').innerHTML=({overview,schedule,media,processing,scripts,sops,talent,connections})[route]();document.title=routes.find(r=>r[0]===route)[2]+' · The Program';bindView()}
function confirmAction(message,action){modal('Confirm change',`<p>${esc(message)}</p>`,`<button class="btn" id="cancel-confirm">Cancel</button><button class="btn primary" id="accept-confirm">Confirm</button>`);$('#cancel-confirm').onclick=()=>$('#dialog').close();$('#accept-confirm').onclick=action}
function modal(title,body,actions=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();$('#dialog [data-close]').onclick=()=>d.close()}
function field(label,name,value='',type='text',full=false){return `<label class="field ${full?'full':''}">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${['title','date','time'].includes(name)?'required':''}></label>`}
function selectField(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function sessionForm(id){let s=state.sessions.find(x=>x.id===id)||{date:'2026-11-09',time:'10:00',duration:'60',kind:'Recording',status:'Tentative'};modal(id?'Edit session':'Plan a session',`<form id="edit-form"><div class="form-grid">${field('Session title','title',s.title,'text',true)}${field('Date','date',s.date,'date')}${field('Start time · Regina','time',s.time,'time')}${field('Duration in minutes','duration',s.duration,'number')}${selectField('Type','kind',['Recording','Planning','Review','Delivery'],s.kind)}${field('Talent / attendees','talent',s.talent)}${field('Location or meeting link','location',s.location)}${selectField('Status','status',['Tentative','Confirmed','Complete','Cancelled'],s.status)}<label class="field full">Notes<textarea name="notes">${esc(s.notes||'')}</textarea></label></div><div class="row mt"><button class="btn primary" type="submit">Save session</button>${id?'<button class="btn danger" type="button" id="delete-session">Delete session</button>':''}</div><p class="small muted mt">Saved in this browser. No invitations are sent.</p></form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(Number(v.duration)<1||Number(v.duration)>1440)return toast('Choose a duration between 1 and 1,440 minutes.');if(id)Object.assign(s,v);else state.sessions.push({id:uid(),...v});save();$('#dialog').close();render();toast('Session saved locally')};if(id)$('#delete-session').onclick=()=>{confirmAction('Delete this local session?',()=>{state.sessions=state.sessions.filter(x=>x.id!==id);save();$('#dialog').close();render()})}}
function assetForm(id){let a=state.assets.find(x=>x.id===id);modal(a?'Content details':'New content piece',`<form id="edit-form"><div class="form-grid">${field('Title','title',a?.title,'text',true)}${field('Voice / contributor','speaker',a?.speaker)}${selectField('Format','type',['Audio','Video'],a?.type||'Audio')}${field('Program week (optional)','week',a?.week)}${selectField('Stage','stage',stages,a?.stage||'Planned')}</div>${a?`<div class="notice mt"><b>${esc(a.id)}</b> · version ${a.version}<br>File transfer, transcript search and measured audio reports will appear once the backend is connected. Stage changes here are planning labels, not verified approvals.</div><div class="code-name">${esc(a.id)}_${esc(a.title.toLowerCase().replace(/[^a-z0-9]+/g,'-'))}_master_v${String(a.version).padStart(3,'0')}.wav</div>`:''}<button class="btn primary mt" type="submit">Save content piece</button></form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(a)Object.assign(a,v);else{let n=Math.max(0,...state.assets.map(a=>Number(a.id.replace('AO-',''))||0))+1;state.assets.push({id:'AO-'+String(n).padStart(4,'0'),...v,version:1,duration:'—'})}save();$('#dialog').close();render();toast('Content record saved locally')}}
function docForm(kind,id){let list=state[kind],d=list.find(x=>x.id===id),isSop=kind==='sops';modal(d?d.title:isSop?'New procedure':'New script',`<form id="edit-form"><div class="form-grid">${d?.sourceUrl==='/guides/sound-design-sop.pdf'?'<div class="field full"><a class="btn" href="/guides/sound-design-sop.pdf" target="_blank" rel="noopener">Open original PDF ↗</a><a class="text-link" href="/guides/sound-design-sop.pdf" download>Download original PDF ↓</a><span class="small muted">Source dated November 4, 2026 · no source version or approval recorded</span></div>':''}${field('Title','title',d?.title,'text',true)}${isSop?field('Category','category',d?.category||'Recording')+field('Owner','owner',d?.owner||'Owner to assign'):field('Content ID','piece',d?.piece)+field('Assigned talent','talent',d?.talent)}${selectField('Status','status',['Draft','Approved','Archived'],d?.status||'Draft')}${isSop?field('Short description','summary',d?.summary,'text',true):''}<label class="field full">${isSop?'Procedure and checklist':'Script text'}<textarea name="body" required style="min-height:250px">${esc(d?.body||'')}</textarea></label></div><div class="notice mt">${isSop?'Changes create a new local version. Approval here is a preview workflow, not a shared team sign-off.':'Editing an approved script returns it to Draft and resets talent acknowledgement. Reapprove the new version before downloading it from the talent portal.'}</div><div class="row"><button class="btn primary" type="submit">Save ${isSop?'procedure':'script'}</button>${d?`<button class="btn" type="button" id="download-doc">Download .txt ↓</button><button class="btn" type="button" id="print-doc">Print / PDF</button>`:''}</div>${d?.history?.length?`<details class="mt"><summary class="small muted">${d.history.length} earlier version(s)</summary>${d.history.map(h=>`<div class="small muted" style="padding:10px 0;border-bottom:1px solid var(--line)">v${h.version} · ${esc(h.status)}<pre class="reading">${esc(h.body)}</pre></div>`).join('')}</details>`:''}</form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(d){let changed=['title','body',...(isSop?['category','summary','owner']:['piece','talent'])].some(k=>v[k]!==d[k]);if(changed){const snapshot=Object.fromEntries(Object.entries(d).filter(([key])=>key!=='history'));d.history=[...(d.history||[]),{...snapshot,savedAt:new Date().toISOString()}];v.version=d.version+1;if(d.status==='Approved')v.status='Draft';if(!isSop)v.ack=false}Object.assign(d,v)}else list.push({id:uid(),...v,version:1,...(!isSop?{ack:false}:{})});save();$('#dialog').close();render();toast('Saved locally'+(d?.status==='Draft'?' · draft version':''))};if(d){$('#download-doc').onclick=()=>downloadDoc(d,isSop);$('#print-doc').onclick=()=>printDoc(d,isSop)}}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadDoc(d,sop=false){download(`${(d.piece||'SOP')}_${d.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}_v${String(d.version).padStart(3,'0')}.txt`,`THE PROGRAM · ${sop?'PROCEDURE':'SCRIPT'}\nLOCAL PREVIEW COPY\n${d.title}\nVersion ${d.version} · ${d.status}\n${d.talent||d.owner||''}\n\n${d.body}\n\nDownloaded ${new Date().toISOString()}. Check the workspace for a newer approved version.`)}
function stageFiles(files){let rejected=0;for(const f of files){if(!/^(audio|video)\//.test(f.type)&&! /\.(wav|mp3|m4a|mov|mp4|mxf)$/i.test(f.name)){rejected++;continue}if(!state.queue.some(q=>q.name===f.name&&q.size===f.size&&q.modified===f.lastModified))state.queue.push({id:uid(),name:f.name,size:f.size,modified:f.lastModified})}save();render();toast(rejected?`${rejected} unsupported file(s) skipped. Media details staged locally.`:'File details staged locally. Original files have not been uploaded.')}
function searchDialog(){modal('Find something at the desk',`<input class="w-full" id="global-search" placeholder="Search titles, scripts and procedures…" aria-label="Search workspace"><div id="search-results" class="mt"><p class="muted small">Searches local records and document text. Media transcripts will be searchable after the local worker is connected.</p></div>`);$('#global-search').oninput=e=>{let q=e.target.value.toLowerCase().trim();let results=q?[...state.assets.map(d=>({...d,kind:'media'})),...state.scripts.map(d=>({...d,kind:'scripts'})),...state.sops.map(d=>({...d,kind:'sops'})),...state.sessions.map(d=>({...d,kind:'schedule'}))].filter(d=>[d.title,d.id,d.body,d.speaker,d.talent].join(' ').toLowerCase().includes(q)):[];$('#search-results').innerHTML=results.map(d=>`<button class="search-result w-full" style="text-align:left;background:none;border-left:0;border-right:0;border-top:0" data-search-result="${d.kind}" data-id="${d.id}"><span class="eyebrow" style="font-size:8px">${d.kind}</span><br>${esc(d.title)}</button>`).join('')||'<p class="small muted">No matching records.</p>'};$('#global-search').focus()}
function icsEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function calendarExport(){let events=state.sessions.filter(s=>s.status!=='Cancelled').map(s=>{let start=new Date(s.date+'T'+s.time+':00-06:00'),end=new Date(+start+Number(s.duration)*60000),fmt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');return `BEGIN:VEVENT\r\nUID:${s.id}@production-desk\r\nDTSTAMP:${fmt(new Date())}\r\nDTSTART:${fmt(start)}\r\nDTEND:${fmt(end)}\r\nSUMMARY:${icsEscape(s.title)}\r\nLOCATION:${icsEscape(s.location)}\r\nDESCRIPTION:${icsEscape(s.notes+'\nLocal planning export. Attendees: '+s.talent)}\r\nSTATUS:${s.status==='Tentative'?'TENTATIVE':'CONFIRMED'}\r\nEND:VEVENT`});download('program-production-schedule.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//The Program//Production Desk//EN\r\nCALSCALE:GREGORIAN\r\n${events.join('\r\n')}\r\nEND:VCALENDAR\r\n`,'text/calendar')}
function validateImport(data){for(let k of ['assets','sessions','scripts','sops','tasks','queue'])if(!Array.isArray(data[k])||data[k].length>10000)throw Error('Invalid workspace structure');for(let [k,fields]of Object.entries({assets:['id','title','speaker','type','stage','week','duration'],sessions:['id','title','date','time','duration','talent','location','kind','status','notes'],scripts:['id','title','piece','talent','status','body'],sops:['id','title','category','owner','status','summary','body'],tasks:['id','title'],queue:['id','name']})){for(let d of data[k]){if(!d||typeof d.id!=='string'||! /^[a-zA-Z0-9_-]+$/.test(d.id)||fields.some(f=>typeof d[f]!=='string'))throw Error('Invalid record in '+k);if(['assets','scripts','sops'].includes(k)&&(!Number.isInteger(d.version)||d.version<1))throw Error('Invalid version')}}return data}
function bindView(){if($('#filter'))$('#filter').oninput=e=>{let pos=e.target.selectionStart;filter=e.target.value;render();$('#filter').focus();$('#filter').setSelectionRange(pos,pos)};for(let id of ['status-filter','category-filter'])if($('#'+id))$('#'+id).onchange=e=>{tabFilter=e.target.value;render()};if($('#file-input'))$('#file-input').onchange=e=>stageFiles(e.target.files);if($('#dropzone')){let dz=$('#dropzone');dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();stageFiles(e.dataTransfer.files)}}if($('#import-input'))$('#import-input').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>10000000)throw Error('Backup too large');let d=validateImport(JSON.parse(await f.text()));confirmAction('Replace this browser’s workspace with the selected backup?',()=>{state=d;save();$('#dialog').close();render();toast('Workspace restored locally')})}catch{toast('This file is not a valid Production Desk backup.')}}}
document.addEventListener('change',e=>{if(e.target.dataset.task){let t=state.tasks.find(x=>x.id===e.target.dataset.task);t.done=e.target.checked;save();render()}if(e.target.dataset.stage){state.assets.find(x=>x.id===e.target.dataset.stage).stage=e.target.value;save();toast('Planning stage saved locally')}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.session)return sessionForm(d.session);if(d.asset)return assetForm(d.asset);if(d.script)return docForm('scripts',d.script);if(d.sop){if(demoRole==='talent'){let guide=state.sops.find(x=>x.id===d.sop);return modal(guide.title,`${tag(guide.status)}<p class="reading mt">${esc(guide.body)}</p>`)}return docForm('sops',d.sop);}if(d.view){scheduleView=d.view;return render()}if(d.month){month+=Number(d.month);if(month<0){month=11;year--}if(month>11){month=0;year++}return render()}if(d.tab){tabFilter=d.tab;return render()}if(d.connect){let i=integrations.find(i=>i.name===d.connect);return modal(i.name+' setup',`<p>${i.desc}</p><div class="section-label mt">REQUIRED TO CONNECT</div><p class="reading">${i.needs.split(' · ').map(x=>'□ '+esc(x)).join('\n')}</p><div class="notice mt">This is a setup placeholder. No connection has been made. Credentials must be configured securely on the backend, never stored in this preview.</div>`)}if(d.removeQueue){state.queue=state.queue.filter(q=>q.id!==d.removeQueue);save();return render()}if(d.action==='processing-setup'){return modal('Processing is not connected',`<p>Configure the company Auphonic account and approve a preset before enabling submissions.</p><div class="notice mt">No audio has been sent and no processing credits have been used.</div>`)}if(d.readScript){let s=state.scripts.find(x=>x.id===d.readScript);return modal(s.title,`<div class="row">${tag(s.status)}<span class="small muted">Version ${s.version}</span></div><p class="reading mt">${esc(s.body)}</p>`)}if(d.downloadScript){let s=state.scripts.find(x=>x.id===d.downloadScript);if(s.status==='Approved')downloadDoc(s);return}if(d.ack){state.scripts.find(x=>x.id===d.ack).ack=true;save();render();return toast('Marked reviewed locally · not shared with the team')}if(d.searchResult){$('#dialog').close();if(d.searchResult==='media')assetForm(d.id);else if(d.searchResult==='schedule')sessionForm(d.id);else docForm(d.searchResult,d.id);return}switch(d.action){case'logout':demoRole=null;try{sessionStorage.removeItem('program-demo-role')}catch{}location.hash='home';return render();case'new-session':return sessionForm();case'new-asset':return assetForm();case'new-script':return docForm('scripts');case'new-sop':return docForm('sops');case'choose-files':return $('#file-input').click();case'search':return searchDialog();case'calendar-export':return calendarExport();case'workspace-export':return download('program-workspace-backup.json',JSON.stringify(state,null,2),'application/json');case'workspace-import':return $('#import-input').click();case'catalogue-export':{let cols=['id','title','speaker','type','stage','week','version'];return download('program-catalogue.csv',cols.join(',')+'\r\n'+state.assets.map(a=>cols.map(k=>'"'+String(a[k]??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv')}case'reset':confirmAction('Replace local records with the original example data? Export a backup first if needed.',()=>{state=structuredClone(seed);save();$('#dialog').close();render();toast('Example data restored')});break}});
$('.mobile-toggle').onclick=()=>document.body.classList.toggle('nav-open');$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});window.addEventListener('hashchange',()=>{filter='';tabFilter='All';document.body.classList.remove('nav-open');render();window.scrollTo(0,0)});document.addEventListener('keydown',e=>{if(!document.body.classList.contains('landing-mode')&&demoRole==='production'&&(e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();searchDialog()}});render();
